-- =====================================================================
--  Pharmacy Inventory & Sales Management System  -  PostgreSQL 14+ port
--  CS220 Database Systems | BESE 2K25 | NUST Islamabad
--  Week 16 : Utilization of PostgreSQL
--  File 1 of 5 : DATABASE + TABLES
--  Run with :  psql -U postgres -f pg_01_schema.sql      (then pg_02 ... pg_05)
--
--  What changes compared with MySQL (details in the report, chapter 13):
--    AUTO_INCREMENT      -> GENERATED BY DEFAULT AS IDENTITY
--    ENUM(...) column    -> CREATE TYPE ... AS ENUM
--    DATETIME            -> TIMESTAMP        TINYINT -> SMALLINT
--    REGEXP              -> ~                no UNSIGNED, no "AFTER column"
--  PostgreSQL extras used : generated column, partial index, expression index,
--    GIN full-text index, materialized view, JSONB.
-- =====================================================================
\set ON_ERROR_STOP on

DROP DATABASE IF EXISTS pharmacy_db;
CREATE DATABASE pharmacy_db;
\connect pharmacy_db

-- ---------------------------------------------------------------------
-- Enumerated types
-- ---------------------------------------------------------------------
CREATE TYPE po_status_t       AS ENUM ('Pending', 'Received', 'Cancelled');
CREATE TYPE employee_role_t   AS ENUM ('Pharmacist', 'Cashier', 'Manager', 'Inventory Clerk');
CREATE TYPE shift_t           AS ENUM ('Morning', 'Evening', 'Night');
CREATE TYPE payment_method_t  AS ENUM ('Cash', 'Card', 'Mobile Wallet');
CREATE TYPE alert_type_t      AS ENUM ('LOW_STOCK', 'NEAR_EXPIRY', 'EXPIRED');

-- ---------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------
CREATE TABLE categories (
    category_id    INT GENERATED BY DEFAULT AS IDENTITY,
    category_name  VARCHAR(60)  NOT NULL,
    description    VARCHAR(200),
    CONSTRAINT pk_categories    PRIMARY KEY (category_id),
    CONSTRAINT uq_category_name UNIQUE (category_name)
);

CREATE TABLE suppliers (
    supplier_id  INT GENERATED BY DEFAULT AS IDENTITY,
    name         VARCHAR(100) NOT NULL,
    phone        VARCHAR(15)  NOT NULL,
    address      VARCHAR(200) NOT NULL,
    is_active    BOOLEAN      NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_suppliers      PRIMARY KEY (supplier_id),
    CONSTRAINT uq_supplier_name  UNIQUE (name),
    CONSTRAINT uq_supplier_phone UNIQUE (phone),
    CONSTRAINT ck_supplier_phone CHECK (phone ~ '^[0-9]{3,4}-[0-9]{7}$')
);

CREATE TABLE products (
    product_id             INT GENERATED BY DEFAULT AS IDENTITY,
    name                   VARCHAR(100)  NOT NULL,
    generic_name           VARCHAR(100),
    category_id            INT           NOT NULL,
    unit_price             NUMERIC(10,2) NOT NULL,
    reorder_level          INT           NOT NULL DEFAULT 20,
    requires_prescription  BOOLEAN       NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_products          PRIMARY KEY (product_id),
    CONSTRAINT uq_product_name      UNIQUE (name),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id)
        REFERENCES categories (category_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_product_price     CHECK (unit_price >= 0),
    CONSTRAINT ck_product_reorder   CHECK (reorder_level >= 0)
);

CREATE TABLE purchase_orders (
    po_id        INT GENERATED BY DEFAULT AS IDENTITY,
    supplier_id  INT           NOT NULL,
    order_date   DATE          NOT NULL DEFAULT CURRENT_DATE,
    status       po_status_t   NOT NULL DEFAULT 'Pending',
    total_cost   NUMERIC(12,2) NOT NULL DEFAULT 0,
    CONSTRAINT pk_purchase_orders PRIMARY KEY (po_id),
    CONSTRAINT fk_po_supplier     FOREIGN KEY (supplier_id)
        REFERENCES suppliers (supplier_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_po_total        CHECK (total_cost >= 0)
);

CREATE TABLE stock_batches (
    batch_id      INT GENERATED BY DEFAULT AS IDENTITY,
    product_id    INT           NOT NULL,
    po_id         INT           NOT NULL,
    batch_no      VARCHAR(30)   NOT NULL,
    received_qty  INT           NOT NULL,
    quantity      INT           NOT NULL,
    expiry_date   DATE          NOT NULL,
    cost_price    NUMERIC(10,2) NOT NULL,
    CONSTRAINT pk_stock_batches  PRIMARY KEY (batch_id),
    CONSTRAINT uq_batch_lot      UNIQUE (product_id, batch_no),
    CONSTRAINT fk_batch_product  FOREIGN KEY (product_id)
        REFERENCES products (product_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_batch_po       FOREIGN KEY (po_id)
        REFERENCES purchase_orders (po_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_batch_received CHECK (received_qty > 0),
    CONSTRAINT ck_batch_quantity CHECK (quantity >= 0 AND quantity <= received_qty),
    CONSTRAINT ck_batch_cost     CHECK (cost_price >= 0)
);

CREATE TABLE customers (
    customer_id    INT GENERATED BY DEFAULT AS IDENTITY,
    name           VARCHAR(100) NOT NULL,
    phone          VARCHAR(15),
    registered_on  DATE         NOT NULL DEFAULT CURRENT_DATE,
    CONSTRAINT pk_customers      PRIMARY KEY (customer_id),
    CONSTRAINT uq_customer_phone UNIQUE (phone),
    CONSTRAINT ck_customer_phone CHECK (phone IS NULL OR phone ~ '^[0-9]{3,4}-[0-9]{7}$')
);

CREATE TABLE employees (
    employee_id  INT GENERATED BY DEFAULT AS IDENTITY,
    name         VARCHAR(100)    NOT NULL,
    role         employee_role_t NOT NULL,
    phone        VARCHAR(15)     NOT NULL,
    hire_date    DATE            NOT NULL,
    is_active    BOOLEAN         NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_employees      PRIMARY KEY (employee_id),
    CONSTRAINT uq_employee_phone UNIQUE (phone),
    CONSTRAINT ck_employee_phone CHECK (phone ~ '^[0-9]{3,4}-[0-9]{7}$')
);

CREATE TABLE pharmacists (                      -- EER subclass
    employee_id    INT          NOT NULL,
    license_no     VARCHAR(20)  NOT NULL,
    qualification  VARCHAR(60)  NOT NULL DEFAULT 'Pharm-D',
    CONSTRAINT pk_pharmacists    PRIMARY KEY (employee_id),
    CONSTRAINT uq_pharmacist_lic UNIQUE (license_no),
    CONSTRAINT fk_pharmacist_emp FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE TABLE cashiers (                         -- EER subclass
    employee_id  INT      NOT NULL,
    shift        shift_t  NOT NULL DEFAULT 'Morning',
    counter_no   SMALLINT NOT NULL,
    CONSTRAINT pk_cashiers        PRIMARY KEY (employee_id),
    CONSTRAINT fk_cashier_emp     FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_cashier_counter CHECK (counter_no BETWEEN 1 AND 6)
);

CREATE TABLE sales (
    sale_id         INT GENERATED BY DEFAULT AS IDENTITY,
    customer_id     INT              NOT NULL,
    employee_id     INT              NOT NULL,
    sale_date       TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    payment_method  payment_method_t NOT NULL DEFAULT 'Cash',
    total_amount    NUMERIC(12,2)    NOT NULL DEFAULT 0,
    CONSTRAINT pk_sales          PRIMARY KEY (sale_id),
    CONSTRAINT fk_sales_customer FOREIGN KEY (customer_id)
        REFERENCES customers (customer_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT fk_sales_employee FOREIGN KEY (employee_id)
        REFERENCES employees (employee_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_sales_total    CHECK (total_amount >= 0)
);

CREATE TABLE sale_items (
    sale_id     INT           NOT NULL,
    product_id  INT           NOT NULL,
    quantity    INT           NOT NULL,
    unit_price  NUMERIC(10,2) NOT NULL,
    line_total  NUMERIC(12,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,   -- PostgreSQL generated column
    CONSTRAINT pk_sale_items    PRIMARY KEY (sale_id, product_id),
    CONSTRAINT fk_item_sale     FOREIGN KEY (sale_id)
        REFERENCES sales (sale_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_item_product  FOREIGN KEY (product_id)
        REFERENCES products (product_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_item_quantity CHECK (quantity > 0),
    CONSTRAINT ck_item_price    CHECK (unit_price >= 0)
);

CREATE TABLE sale_allocations (
    sale_id     INT           NOT NULL,
    product_id  INT           NOT NULL,
    batch_id    INT           NOT NULL,
    quantity    INT           NOT NULL,
    cost_price  NUMERIC(10,2) NOT NULL,
    CONSTRAINT pk_sale_alloc  PRIMARY KEY (sale_id, product_id, batch_id),
    CONSTRAINT fk_alloc_item  FOREIGN KEY (sale_id, product_id)
        REFERENCES sale_items (sale_id, product_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_alloc_batch FOREIGN KEY (batch_id)
        REFERENCES stock_batches (batch_id) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_alloc_qty   CHECK (quantity > 0),
    CONSTRAINT ck_alloc_cost  CHECK (cost_price >= 0)
);

CREATE TABLE stock_alerts (
    alert_id    INT GENERATED BY DEFAULT AS IDENTITY,
    alert_type  alert_type_t  NOT NULL,
    product_id  INT           NOT NULL,
    batch_id    INT,
    message     VARCHAR(255)  NOT NULL,
    created_at  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_stock_alerts  PRIMARY KEY (alert_id),
    CONSTRAINT fk_alert_product FOREIGN KEY (product_id) REFERENCES products (product_id) ON DELETE CASCADE,
    CONSTRAINT fk_alert_batch   FOREIGN KEY (batch_id)   REFERENCES stock_batches (batch_id) ON DELETE SET NULL
);

CREATE TABLE audit_log (
    log_id      INT GENERATED BY DEFAULT AS IDENTITY,
    table_name  VARCHAR(40)  NOT NULL,
    record_id   INT          NOT NULL,
    action      VARCHAR(20)  NOT NULL,
    old_value   VARCHAR(255),
    new_value   VARCHAR(255),
    changed_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    changed_by  VARCHAR(80)  NOT NULL DEFAULT CURRENT_USER,
    CONSTRAINT pk_audit_log PRIMARY KEY (log_id)
);

-- ---------------------------------------------------------------------
-- Indexes (including PostgreSQL-only kinds)
-- ---------------------------------------------------------------------
CREATE INDEX idx_products_category ON products (category_id);
CREATE INDEX idx_batches_expiry    ON stock_batches (expiry_date);
CREATE INDEX idx_batches_fefo      ON stock_batches (product_id, expiry_date) WHERE quantity > 0;   -- partial index
CREATE INDEX idx_sales_day         ON sales ((sale_date::date));                                     -- expression index
CREATE INDEX idx_sales_customer    ON sales (customer_id);
CREATE INDEX idx_sales_employee    ON sales (employee_id);
CREATE INDEX idx_items_product     ON sale_items (product_id);
CREATE INDEX idx_po_supplier       ON purchase_orders (supplier_id);
CREATE INDEX idx_products_fts      ON products USING GIN                                              -- full-text search
       (to_tsvector('english', name || ' ' || COALESCE(generic_name, '')));

-- ---------------------------------------------------------------------
-- DDL demonstration : ALTER TABLE
-- ---------------------------------------------------------------------
ALTER TABLE customers ADD COLUMN email VARCHAR(100), ADD CONSTRAINT uq_customer_email UNIQUE (email);
ALTER TABLE suppliers ALTER COLUMN address TYPE VARCHAR(250);
ALTER TABLE products  ADD COLUMN manufacturer VARCHAR(80);

\dt
